//! Parity with AutoDock Vina 1.2.7 on a fixed set of PoseBusters complexes.
//!
//! The fixtures in `tests/parity_data/` and Vina's scores in `golden.tsv`
//! are generated by `benchmark/parity/make_golden.py`. The scoring tests are
//! fast and always run; the docking test is `#[ignore]`d and run in release
//! mode by CI: `cargo test --release --test parity -- --ignored`.

use assert_approx_eq::assert_approx_eq;
use nalgebra::Vector3;
use rustdock_vina::forcefield::vina::VinaForceField;
use rustdock_vina::forcefield::vinardo::VinardoForceField;
use rustdock_vina::forcefield::ForceField;
use rustdock_vina::io::{parse_flex_pdbqt, parse_pdbqt};
use rustdock_vina::optimization::monte_carlo::{MonteCarlo, MonteCarloParams};
use rustdock_vina::scoring::{score_pose, score_pose_with_flex};
use rustdock_vina::{ligand_internal_energy, rmsd_bounds, FlexResidues, Molecule};
use std::collections::HashMap;
use std::path::PathBuf;

/// Largest difference from Vina allowed for a score, in kcal/mol. On these
/// fixtures rustdock is within 0.016 of Vina's three printed decimals, so a
/// 0.3% change to one Vina weight already fails.
const SCORE_TOLERANCE: f64 = 0.02;

/// How much worse than Vina's top affinity rustdock's may be when docking.
const DOCK_AFFINITY_SLACK: f64 = 0.3;

/// Success threshold for the top pose's heavy-atom RMSD to the crystal pose.
const DOCK_RMSD_LIMIT: f64 = 2.0;

fn data_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("parity_data")
}

/// One row of `golden.tsv`: column name to value.
struct Complex(HashMap<String, String>);

impl Complex {
    fn code(&self) -> &str {
        &self.0["code"]
    }

    fn value(&self, column: &str) -> f64 {
        self.0[column]
            .parse()
            .unwrap_or_else(|_| panic!("{}: bad {column}: {:?}", self.code(), self.0[column]))
    }

    fn vector(&self, prefix: &str) -> Vector3<f64> {
        Vector3::new(
            self.value(&format!("{prefix}_x")),
            self.value(&format!("{prefix}_y")),
            self.value(&format!("{prefix}_z")),
        )
    }

    fn docked(&self) -> bool {
        self.0["dock"] == "True"
    }

    /// Whether the complex has flexible side chains (`flex.pdbqt`).
    fn flexible(&self) -> bool {
        self.0.get("flex_residues").is_some_and(|r| !r.is_empty())
    }

    fn load(&self, file: &str) -> Molecule {
        let path = data_dir().join(self.code()).join(file);
        parse_pdbqt(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
    }

    /// The rigid receptor and flexible side chains.
    fn load_flex(&self) -> (Molecule, FlexResidues) {
        let rigid = self.load("flex_rigid.pdbqt");
        let path = data_dir().join(self.code()).join("flex.pdbqt");
        let flex =
            parse_flex_pdbqt(&path, &rigid).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        (rigid, flex)
    }

    /// Whether Vina docked the complex with its flexible side chains.
    fn flex_docked(&self) -> bool {
        self.0
            .get("vina_flex_dock_affinity")
            .is_some_and(|v| !v.is_empty())
    }
}

fn golden() -> Vec<Complex> {
    let text = std::fs::read_to_string(data_dir().join("golden.tsv")).expect("golden.tsv");
    let mut lines = text.lines();
    let header: Vec<&str> = lines.next().expect("header").split('\t').collect();
    lines
        .map(|line| {
            Complex(
                header
                    .iter()
                    .zip(line.split('\t'))
                    .map(|(k, v)| (k.to_string(), v.to_string()))
                    .collect(),
            )
        })
        .collect()
}

/// Scores `ligand` of every complex and compares the intermolecular energy and
/// affinity with Vina's `<prefix>_inter` and `<prefix>_affinity`, reporting
/// every mismatch at once.
fn check_scores(forcefield: &dyn ForceField, ligand: &str, prefix: &str) {
    let complexes = golden();
    assert!(complexes.len() >= 15, "golden.tsv has too few complexes");
    let mut failures = Vec::new();
    for complex in &complexes {
        let receptor = complex.load("receptor.pdbqt");
        let pose = complex.load(ligand);
        let score = score_pose(&pose, &receptor, forcefield).expect("score");
        for (name, ours) in [
            ("inter", score.intermolecular),
            ("affinity", score.affinity),
        ] {
            let vina = complex.value(&format!("{prefix}_{name}"));
            if (ours - vina).abs() > SCORE_TOLERANCE {
                failures.push(format!(
                    "{} {name}: rustdock {ours:.3}, Vina {vina:.3} (diff {:+.3})",
                    complex.code(),
                    ours - vina
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} {ligand} scores differ from Vina 1.2.7 by more than {SCORE_TOLERANCE}:\n  {}",
        forcefield.name(),
        failures.join("\n  ")
    );
}

/// Scores the crystal pose of every complex with flexible side chains and
/// compares each energy term with Vina's `<scoring>_flex_*` columns.
fn check_flex_scores(forcefield: &dyn ForceField, scoring: &str) {
    let complexes: Vec<_> = golden().into_iter().filter(Complex::flexible).collect();
    assert!(
        complexes.len() >= 5,
        "golden.tsv has too few flex complexes"
    );
    let mut failures = Vec::new();
    for complex in &complexes {
        let (rigid, flex) = complex.load_flex();
        let pose = complex.load("ligand_xtal.pdbqt");
        let score = score_pose_with_flex(&pose, &rigid, Some(&flex), forcefield).expect("score");
        for (name, ours) in [
            ("inter", score.intermolecular),
            ("affinity", score.affinity),
            ("lig_flex", score.ligand_flex),
            ("flex_rec", score.flex_receptor),
            ("flex_flex", score.flex_flex),
        ] {
            let vina = complex.value(&format!("{scoring}_flex_{name}"));
            if (ours - vina).abs() > SCORE_TOLERANCE {
                failures.push(format!(
                    "{} {name}: rustdock {ours:.3}, Vina {vina:.3} (diff {:+.3})",
                    complex.code(),
                    ours - vina
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} flex scores differ from Vina 1.2.7 by more than {SCORE_TOLERANCE}:\n  {}",
        forcefield.name(),
        failures.join("\n  ")
    );
}

#[test]
fn crystal_scores_match_vina() {
    check_scores(&VinaForceField::default(), "ligand_xtal.pdbqt", "vina_xtal");
}

#[test]
fn crystal_scores_match_vinardo() {
    check_scores(
        &VinardoForceField::default(),
        "ligand_xtal.pdbqt",
        "vinardo_xtal",
    );
}

#[test]
fn crystal_flex_scores_match_vina() {
    check_flex_scores(&VinaForceField::default(), "vina");
}

#[test]
fn crystal_flex_scores_match_vinardo() {
    check_flex_scores(&VinardoForceField::default(), "vinardo");
}

/// Vina's own top docked pose, read from its output, scores as Vina scores it.
#[test]
fn vina_poses_rescore() {
    check_scores(&VinaForceField::default(), "vina_top.pdbqt", "vina_top");
}

/// Heavy-atom RMSD in atom order, without superposition: Vina's
/// `rmsd u.b.`, which the library computes for a run's own modes.
fn heavy_rmsd(a: &Molecule, b: &Molecule) -> f64 {
    rmsd_bounds(a, b).expect("heavy atom counts differ").1
}

/// Docking from an RDKit conformer finds the crystal pose, as Vina does.
///
/// The thresholds are loose on purpose: floating-point differences between
/// CPUs can change a search's trajectory, so this guards against search
/// regressions rather than checking exact poses.
#[test]
#[ignore = "slow in debug builds; CI runs it with --release -- --ignored"]
fn docking_finds_crystal_pose() {
    let forcefield = VinaForceField::default();
    let optimizer = MonteCarlo::with_params(MonteCarloParams {
        seed: Some(42),
        ..MonteCarloParams::default()
    });
    let docked: Vec<_> = golden().into_iter().filter(Complex::docked).collect();
    assert!(!docked.is_empty(), "golden.tsv has no docking complexes");

    let mut failures = Vec::new();
    for complex in &docked {
        let receptor = complex.load("receptor.pdbqt");
        let ligand = complex.load("ligand_start.pdbqt");
        let crystal = complex.load("ligand_xtal.pdbqt");
        let target = optimizer
            .target(
                receptor,
                &forcefield,
                complex.vector("center"),
                complex.vector("size"),
            )
            .expect("target");
        let results = optimizer
            .dock_into(&target, &ligand, &forcefield, 9, 0)
            .expect("dock");
        let top = results.first().expect("at least one pose");
        let affinity =
            forcefield.apply_torsional_normalization(top.energy, ligand.vina_torsion_count());
        let rmsd = heavy_rmsd(&top.molecule, &crystal);
        let vina = complex.value("vina_dock_affinity");
        println!(
            "{}: affinity {affinity:.3} (Vina {vina:.3}), top-1 RMSD {rmsd:.2} A (Vina {:.2})",
            complex.code(),
            complex.value("vina_dock_rmsd")
        );
        if rmsd >= DOCK_RMSD_LIMIT {
            failures.push(format!("{}: top-1 RMSD {rmsd:.2} A", complex.code()));
        }
        if affinity > vina + DOCK_AFFINITY_SLACK {
            failures.push(format!(
                "{}: affinity {affinity:.3}, Vina {vina:.3}",
                complex.code()
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Docking with flexible side chains reaches Vina's top affinity, and on the
/// complex where Vina also finds the crystal pose (`flex_dock`), so does
/// rustdock.
#[test]
#[ignore = "slow in debug builds; CI runs it with --release -- --ignored"]
fn flex_docking_matches_vina() {
    let forcefield = VinaForceField::default();
    let optimizer = MonteCarlo::with_params(MonteCarloParams {
        seed: Some(42),
        ..MonteCarloParams::default()
    });
    let docked: Vec<_> = golden().into_iter().filter(Complex::flex_docked).collect();
    assert!(
        !docked.is_empty(),
        "golden.tsv has no flex docking complexes"
    );
    assert!(docked.iter().any(|c| c.0["flex_dock"] == "True"));

    let mut failures = Vec::new();
    for complex in &docked {
        let (rigid, flex) = complex.load_flex();
        let ligand = complex.load("ligand_start.pdbqt");
        let crystal = complex.load("ligand_xtal.pdbqt");
        let target = optimizer
            .target_with_flex(
                rigid,
                flex,
                &forcefield,
                complex.vector("flex_center"),
                complex.vector("flex_size"),
            )
            .expect("target");
        let results = optimizer
            .dock_into(&target, &ligand, &forcefield, 9, 0)
            .expect("dock");
        let top = results.first().expect("at least one pose");
        assert!(
            top.flex.is_some(),
            "{}: no side chains in the result",
            complex.code()
        );
        let affinity =
            forcefield.apply_torsional_normalization(top.energy, ligand.vina_torsion_count());
        let rmsd = heavy_rmsd(&top.molecule, &crystal);
        let vina = complex.value("vina_flex_dock_affinity");
        println!(
            "{}: affinity {affinity:.3} (Vina {vina:.3}), top-1 RMSD {rmsd:.2} A (Vina {:.2})",
            complex.code(),
            complex.value("vina_flex_dock_rmsd")
        );
        if complex.0["flex_dock"] == "True" && rmsd >= DOCK_RMSD_LIMIT {
            failures.push(format!("{}: top-1 RMSD {rmsd:.2} A", complex.code()));
        }
        if affinity > vina + DOCK_AFFINITY_SLACK {
            failures.push(format!(
                "{}: affinity {affinity:.3}, Vina {vina:.3}",
                complex.code()
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// One docked mode of `vina_modes.pdbqt`, with the numbers Vina printed for
/// it: the two RMSD bounds and the internal energy.
struct ModeRemarks {
    rmsd_lb: f64,
    rmsd_ub: f64,
    intra: f64,
}

/// The nine modes of `5S8I_2LY/vina_modes.pdbqt`, a docking written by
/// AutoDock Vina 1.2.7, each parsed back into a `Molecule` beside the
/// remarks Vina wrote for that pose. Checking against these tests a
/// measurement on its own, with no search in the way.
fn vina_modes() -> Vec<(Molecule, ModeRemarks)> {
    let path = data_dir().join("5S8I_2LY").join("vina_modes.pdbqt");
    let text = std::fs::read_to_string(&path).expect("read vina_modes.pdbqt");

    let numbers = |rest: &str| -> Vec<f64> {
        rest.split_whitespace()
            .map(|v| v.parse().expect("number in a REMARK"))
            .collect()
    };

    let mut models: Vec<String> = Vec::new();
    let mut remarks: Vec<ModeRemarks> = Vec::new();
    for line in text.lines() {
        if line.starts_with("MODEL") {
            models.push(String::new());
            remarks.push(ModeRemarks {
                rmsd_lb: f64::NAN,
                rmsd_ub: f64::NAN,
                intra: f64::NAN,
            });
        } else if let Some(rest) = line.strip_prefix("REMARK VINA RESULT:") {
            let values = numbers(rest);
            let mode = remarks.last_mut().expect("REMARK before MODEL");
            (mode.rmsd_lb, mode.rmsd_ub) = (values[1], values[2]);
        } else if let Some(rest) = line.strip_prefix("REMARK INTRA:") {
            remarks.last_mut().expect("REMARK before MODEL").intra = numbers(rest)[0];
        } else if let Some(model) = models.last_mut() {
            // `REMARK INTER + INTRA` and the rest are the molecule's own
            // records; the parser keeps them for a round trip.
            model.push_str(line);
            model.push('\n');
        }
    }
    assert_eq!(models.len(), 9, "expected nine modes");

    // The parser reads one model per file, so give each its own.
    let dir = tempfile::tempdir().expect("tempdir");
    models
        .iter()
        .zip(remarks)
        .enumerate()
        .map(|(i, (model, mode))| {
            assert!(
                !mode.rmsd_lb.is_nan() && !mode.intra.is_nan(),
                "mode {i} is missing a remark"
            );
            let file = dir.path().join(format!("mode{i}.pdbqt"));
            std::fs::write(&file, model).expect("write mode");
            let pose = parse_pdbqt(&file).unwrap_or_else(|e| panic!("mode {i}: {e}"));
            (pose, mode)
        })
        .collect()
}

/// rustdock's `rmsd l.b.` and `rmsd u.b.` are Vina's.
///
/// `vina_modes.pdbqt` is a nine-mode docking written by AutoDock Vina
/// 1.2.7, so each mode's `REMARK VINA RESULT` carries the two distances
/// Vina measured from its own best pose. Recomputing them from the poses
/// in that file checks the measures alone, with no search in the way.
#[test]
fn rmsd_bounds_match_vina() {
    let modes = vina_modes();
    // Vina measures every mode against the best one.
    let best = &modes[0].0;
    for (i, (pose, golden)) in modes.iter().enumerate() {
        let (lb, ub) = rmsd_bounds(pose, best).expect("same atoms");
        // A PDBQT stores three decimals, so these poses are Vina's own
        // rounded to 0.001 A. Recomputing from them lands within 0.0006 of
        // every value Vina printed; a mistake in either measure (counting
        // hydrogens, pairing atoms wrongly, one direction of the lower
        // bound) moves it by far more.
        assert_approx_eq!(lb, golden.rmsd_lb, 1e-3);
        assert_approx_eq!(ub, golden.rmsd_ub, 1e-3);
        let _ = i;
    }

    // The fixture is only worth testing if the two measures differ, which
    // they do wherever like atoms swap places.
    assert!(
        modes.iter().any(|(_, g)| g.rmsd_ub - g.rmsd_lb > 0.5),
        "fixture has no mode where the bounds differ"
    );
}

/// The ligand's internal energy is Vina's.
///
/// Each mode of `vina_modes.pdbqt` carries the `REMARK INTRA` that Vina
/// 1.2.7 computed for that very pose, so this checks the pair list and the
/// energy alone, with no search in the way. Vina counts only pairs whose
/// atoms can move relative to each other; counting the rest adds a constant
/// that cancels out of the affinity but corrupts this number.
#[test]
fn ligand_internal_energy_matches_vina() {
    let forcefield = VinaForceField::default();
    for (i, (pose, golden)) in vina_modes().iter().enumerate() {
        let intra = ligand_internal_energy(pose, &forcefield).expect("score");
        // Within 0.00022 of every value Vina printed, which is PDBQT's
        // three decimals. Counting the pairs inside one rigid body, whose
        // distance never changes, put this 0.078 out on this ligand.
        assert_approx_eq!(intra, golden.intra, 1e-3);
        assert!(
            golden.intra.abs() > 1e-9,
            "mode {i} has no internal energy to compare"
        );
    }
}

/// Every pair the mobility rule drops really does hold a fixed distance.
///
/// The nine modes of `vina_modes.pdbqt` are the same ligand at different
/// torsion angles, chosen by Vina's own search, so a pair whose distance is
/// equal in all of them cannot be moved by any torsion. This checks the
/// rigid bodies that [`Molecule::variable`] reads against data that knows
/// nothing about how rustdock derived them: a wrong body assignment would
/// drop a pair that the torsions do move.
#[test]
fn dropped_intra_pairs_never_move() {
    let modes = vina_modes();
    let reference = &modes[0].0;
    let n = reference.atoms.len();

    let mut dropped = 0usize;
    for a in 0..n {
        for b in (a + 1)..n {
            if reference.variable(a, b) {
                continue;
            }
            let distance = |m: &Molecule| (m.atoms[a].coordinates - m.atoms[b].coordinates).norm();
            let first = distance(reference);
            for (pose, _) in &modes {
                // Coordinates are stored to three decimals, so allow the
                // rounding of two of them.
                assert_approx_eq!(distance(pose), first, 2e-3);
            }
            dropped += 1;
        }
    }
    assert!(dropped > 0, "no pair was dropped, so nothing was checked");

    // And the converse: the torsions do move something, so the fixture is
    // not nine copies of one pose.
    let moved = (0..n)
        .flat_map(|a| ((a + 1)..n).map(move |b| (a, b)))
        .filter(|&(a, b)| reference.variable(a, b))
        .any(|(a, b)| {
            let distance = |m: &Molecule| (m.atoms[a].coordinates - m.atoms[b].coordinates).norm();
            modes
                .iter()
                .any(|(pose, _)| (distance(pose) - distance(reference)).abs() > 0.1)
        });
    assert!(moved, "no variable pair changed distance across the modes");
}

/// Minimizing a pose only improves it, and only nudges it.
///
/// `--local_only` takes the pose as given and runs BFGS from there, so on
/// Vina's own docked pose -- already at a minimum of the same scoring
/// function -- it must not raise the energy, and it must not wander off to
/// a different pose the way a search would. The affinity is checked against
/// Vina's for the crystal pose, which Vina itself minimizes to within a few
/// hundredths.
#[test]
fn local_only_improves_a_pose_without_moving_it() {
    let forcefield = VinaForceField::default();
    let optimizer = MonteCarlo::new();
    for complex in golden().iter().filter(|c| !c.flexible()) {
        let receptor = complex.load("receptor.pdbqt");
        let crystal = complex.load("ligand_xtal.pdbqt");
        let target = optimizer
            .target(
                receptor,
                &forcefield,
                complex.vector("center"),
                complex.vector("size"),
            )
            .expect("target");

        let before = score_pose(&crystal, target.receptor(), &forcefield)
            .expect("score")
            .intermolecular;
        let local = optimizer
            .local_optimize(&target, &crystal, &forcefield)
            .expect("minimize");
        let after = local.pose.energy;
        let moved = heavy_rmsd(&local.pose.molecule, &crystal);

        println!(
            "{}: {before:.3} -> {after:.3} kcal/mol, moved {moved:.2} A",
            complex.code()
        );
        assert!(
            after <= before + 1e-6,
            "{}: minimizing raised the energy, {before:.3} -> {after:.3}",
            complex.code()
        );
        // A local minimization stays local: Vina's own --local_only moves
        // these poses a few tenths of an Angstrom at most.
        assert!(
            moved < 2.0,
            "{}: minimizing moved the pose {moved:.2} A, which is a search, not a nudge",
            complex.code()
        );
    }
}
